import fs from "node:fs";
import path from "node:path";

export const THUMB_WIDTH = 640;

/**
 * Card-sized copy of a repo image, generated by scripts/make-thumbs.mjs before
 * every build. Returns undefined for remote images or when no thumb exists yet.
 */
export function thumbFor(src: string | undefined): string | undefined {
  if (!src?.startsWith("/images/")) return undefined;
  const name = path.basename(src, path.extname(src));
  const thumb = `/images/thumbs/${name}-${THUMB_WIDTH}.webp`;
  return fs.existsSync(path.join(process.cwd(), "public", thumb)) ? thumb : undefined;
}
